entries[4141] = { ["name"] = "Tome of Conjure Food", ["text"] = "Classes: Mage\nRequires Level 6\nUse: Teaches Conjure Food (Rank 1).\n\nConjures 20 muffins, providing the mage and his allies with something to eat.\n\nConjured items disappear if logged out for more than 15 minutes.\nSell Price:\nConjured Muffin\nConjured Item\n\nUse: Restores 61.2 health over 18 sec. Must remain seated while eating." }
entries[4143] = { ["name"] = "Tome of Conjure Food II", ["text"] = "Classes: Mage\nRequires Level 12\nUse: Teaches Conjure Food (Rank 2).\n\nConjures 20 loaves of bread, providing the mage and his allies with something to eat.\n\nConjured items disappear if logged out for more than 15 minutes.\nSell Price:\nConjured Bread\nConjured Item\nRequires Level 5\n\nUse: Restores 243.6 health over 21 sec. Must remain seated while eating." }
entries[4145] = { ["name"] = "Tome of Conjure Mana Gem", ["text"] = "Classes: Mage\nRequires Level 28\nUse: Teaches Conjure Mana Gem.\n\nConjures a mana agate that can be used to instantly restore 390 to 410 mana.\n\nConjured items disappear if logged out for more than 15 minutes.\nSell Price:\nMana Agate\nConjured Item\nBinds when picked up\nUnique\nRequires Level 28\n\nUse: Restores 390 to 410 mana. (2 Min Cooldown)" }
entries[4146] = { ["name"] = "Tome of Polymorph: Sheep", ["text"] = "Classes: Mage\nRequires Level 40\nUse: Teaches Polymorph: Sheep.\n\nTransforms the enemy into a helpless sheep that cannot cast spells or attack and movement speed is reduced by 60% for up to 10 sec.\nSell Price:" }
